export const FASES_EN = {"primeira-onda":{"nome":"The First Wave","objetivo":"Cross the tidal flat and reach the shell.","ensino":"The tide turns every three valid moves. End your third move on firm ground."},"sombra-da-garca":{"nome":"The Heron’s Shadow","objetivo":"Reach the shell without stepping onto the tile the heron will strike next.","ensino":"Take the shelter below the trail to get around the marked tile. The heron’s attack depends on your move count, not your speed."},"busca-e-volta":{"nome":"There and Back","objetivo":"Collect the pearl on the islet and bring it back to the exit.","ensino":"The exit needs the pearl. Move around on firm ground until low tide, then cross the tidal flat again."},"ilhota-perolada":{"nome":"The Islet’s Secret","objetivo":"Reach the pearly shell and open a route back.","ensino":"The lower trail gives you room to time the falling tide before you cross."},"ponta-da-garca":{"nome":"Heron Point","objetivo":"Collect the pearl and reach the exit beyond the bend without getting caught by the heron.","ensino":"The sixth move completes a tide cycle, but the heron strikes on that move too. Check the warning before collecting the pearl."},"praia-fio-de-areia":{"nome":"A Thread of Sand","objetivo":"Cross two tidal flats to reach the shell.","ensino":"Stand on firm sand or higher ground when the tide rises. The lower pocket gives you space to move without entering the water."},"praia-pocas-espelho":{"nome":"Mirror Pools","objetivo":"Collect both pearls from the pockets and return to the exit.","ensino":"Both pools open at the same time. Choose which side to visit first."},"praia-mirante":{"nome":"From Beach to Lookout","objetivo":"Follow the lookout route to the shell.","ensino":"The heron moves to its own rhythm. Check the warning before taking the narrow passage."},"praia-bolso-mare":{"nome":"Tidal Pocket","objetivo":"Bring the islet’s pearl to the exit.","ensino":"There’s safe ground near each tidal flat. Plan your return before you fetch the pearl."},"praia-trilha-das-pedras":{"nome":"The Stone Trail","objetivo":"Cross via the shelter to reach the shell.","ensino":"Use the junction to advance the tide cycle before crossing the last stretch of tidal flat."},"praia-fragmentos-areal":{"nome":"Pearls in the Sand","objetivo":"Collect the pearls without getting caught by the heron.","ensino":"The two routes are different. Plan around both the heron and the tide, then head back to the harbor."},"praia-chefe-vigia-das-ondas":{"nome":"Keeper of the Flats","objetivo":"Cross three tidal flats and reach the shell on higher ground.","ensino":"There’s safe ground between crossings. Circle the patch of sand before the last flat so you can set out at low tide."},"praia-chefe-ponta-da-ressaca":{"nome":"Tide Point","objetivo":"Collect both pearls from the ends of the sandbank, then head up to the exit.","ensino":"The flat on the eastern tip must be dry both ways. Use the pocket beyond the pearl to wait for low tide. The last passage takes you through the center to the exit."},"recife-pedra-firme":{"nome":"Above the Foam","objetivo":"Use the raised sand shelter to reach the shell.","ensino":"You can step onto raised sand, but never onto rocks. Head back to the shelter at low tide."},"recife-duas-pocas":{"nome":"Two Reef Pools","objetivo":"Collect both pearls on opposite sides and return to the exit.","ensino":"The pools connect only at low tide. The side pockets give you firm ground to time your return."},"recife-retorno":{"nome":"Around the Reef","objetivo":"Collect the pearl in the small cove and cross three tidal flats to reach the exit.","ensino":"When the tide rises, use the pockets near the shelter to break the return trip into several tide cycles."},"recife-degraus":{"nome":"Steps of the Ebb","objetivo":"Reach the shell by way of the two sandbanks.","ensino":"Plan when to leave each shelter. Check when the tide turns before stepping onto a flat."},"recife-janelas":{"nome":"Coral Windows","objetivo":"Cross both low-tide openings to reach the shell.","ensino":"The tidal flats come in pairs. Use the pocket of firm sand to time each crossing."},"recife-pedra-oco":{"nome":"Hollow in the Rock","objetivo":"Collect the pearl tucked among the rocks, then head to the exit.","ensino":"The return passage falls at a different point in the cycle. Get the timing right in the pocket near the pearl."},"recife-volta-costao":{"nome":"Along the Rocky Shore","objetivo":"Fetch the pearl on the far shore and return to the rocky-shore exit.","ensino":"You can explore either branch. They’re different distances from the first safe patch of sand."},"recife-pocas-suspensas":{"nome":"Suspended Pools","objetivo":"Collect two pearls from the upper and lower pockets and return to the exit.","ensino":"Use the central corridor to switch shores. The raised shelter lets you prepare for each trip without returning to the start."},"recife-cintura":{"nome":"Belt of Foam","objetivo":"Cross the reef’s narrow middle at low tide, fetch the pearl and find the exit.","ensino":"The same bend can be safe or dangerous depending on which way you travel and when you enter."},"recife-tres-aneis":{"nome":"Three Ebb Rings","objetivo":"Gather all three pearls from the rings and return to the center.","ensino":"You’ll need to reach each branch at a different point in the tide cycle. Count the return moves for every branch too."},"recife-fio-coral":{"nome":"Thread of Coral","objetivo":"Follow the shorter shore to find the hidden shell.","ensino":"There is just one shelter on each sandbank in the detour. Which firm tile sets you up for the easiest crossing?"},"recife-mosaico":{"nome":"Pool Mosaic","objetivo":"Collect the pearls from the mosaic’s branches and reach the exit.","ensino":"Some low-tide shortcuts help on the way out, others on the way back. Find the better route in each direction."},"recife-chefe-guardiao-das-pocas":{"nome":"Guardian of the Pools","objetivo":"Cross the pools and reach the shell at the reef’s tip.","ensino":"The two patches of firm sand let you time the low tide. Check where your third step will land before entering the flat."},"recife-chefe-vigia-do-recife":{"nome":"Reef Lookout","objetivo":"Fetch the pearl from the reef and return to the Arrival Shell.","ensino":"The upper route out and the wet corridor back share the same tide. Use the patches of dry sand to prepare for each crossing."},"mangue-dois-encontros":{"nome":"Neighboring Roots","objetivo":"Guide both crabs to the two shells.","ensino":"The arrow keys move both crabs together. Cross the flats at low tide. At the end, the shore stops whichever crab arrives first."},"mangue-placa":{"nome":"One Waits, One Goes","objetivo":"Get both crabs onto their shells at the same time.","ensino":"Both crabs get the same command. The wall holds one crab in place while the other rounds the bend to its shell."},"mangue-reuniao":{"nome":"Reunion at Mangrove Point","objetivo":"Bring the crabs together at the two shells.","ensino":"Use the walls of the central passage to separate the pair. Get the tide timing right before guiding both back to the shells."},"mangue-duas-veredas":{"nome":"Two Trails","objetivo":"Occupy both shells at the same time.","ensino":"Each trail bends differently. Use the wall to stagger the crabs’ movement, and keep both off the flat when the tide rises."},"mangue-janela-partilhada":{"nome":"A Shared Window","objetivo":"Cross the two tidal flats to reach both shells.","ensino":"The flats don’t start in the same column. Use the upper nook to time both crabs’ arrival at the shelters before crossing together."},"mangue-trinco-salgado":{"nome":"Saltwater Bend","objetivo":"Guide the crabs to the two shells.","ensino":"The crabs start side by side. Neither can use a tile the other occupied at the start of the same move."},"mangue-fragmentos-cruzados":{"nome":"Crossed Pearls","objetivo":"Collect both pearls on opposite shores and reach both shells.","ensino":"Collect the pearls on both shores. The link on the right lets you turn around without losing your route back to the shells."},"mangue-cotovelo":{"nome":"The Root Bend","objetivo":"Guide both crabs around the bend and onto their shells.","ensino":"Go down around the bend while the other crab waits at the edge. Time the crossings so both reach firm ground safely."},"mangue-porteira-encontro":{"nome":"Beyond the Isthmus","objetivo":"Occupy both shells on the same turn.","ensino":"The upper and lower routes are different widths. Use the corners of the shore to approach the shells without funneling both crabs into the same corridor."},"mangue-raizes-em-circuito":{"nome":"A Circuit of Roots","objetivo":"Collect the pearls and guide both crabs to the shells.","ensino":"Fetch the pearls at opposite ends. Use the central loop to rearrange the pair and return to the shells at the right tide."},"mangue-chefe-guardiao-da-raiz":{"nome":"Root Guardian","objetivo":"Guide both crabs to the Guardian’s shells.","ensino":"Go around the roots to split the routes. Get back to firm sand before a flat floods, then use the next low tide to finish the last loop."},"mangue-chefe-dupla-no-mangue":{"nome":"Mangrove Duo","objetivo":"Guide both crabs to the shells without getting caught by the heron’s swoop.","ensino":"The heron alternates between shores. It can strike a stationary crab too, so check both positions before every move."},"enseada-sombra-restinga":{"nome":"Shadow on the Sandbar","objetivo":"Reach the shell while avoiding the heron’s target.","ensino":"Take the dry-sand detour away from the marked area, then cross the wet stretch at low tide."},"enseada-abrigo-ondas":{"nome":"Shelter Between Waves","objetivo":"Use the shelter to get past the water and the heron’s patrol.","ensino":"Raised sand protects you from the tide, but the heron can still swoop down on it."},"enseada-farol-baixo":{"nome":"Race to the Low Lighthouse","objetivo":"Bring the pearl to the Arrival Shell without getting caught by the heron.","ensino":"Your outward and return routes use different wet passages. Use the bends in the shore to time the next swoop."},"enseada-passo-sombra":{"nome":"One Step Ahead of the Shadow","objetivo":"Reach the shell while avoiding the heron and the rising tide.","ensino":"Get through the first wet passage before entering the shell’s corridor. The heron’s target changes with every valid move."},"enseada-vigia-das-pedras":{"nome":"The Rock Lookout","objetivo":"Reach the shell beyond the heron’s two targets.","ensino":"The raised sand won’t flood, but it won’t protect you from a swoop. The heron alternates between two targets."},"enseada-escolha-de-margem":{"nome":"Pick a Shore","objetivo":"Choose the safe shore and reach the shell.","ensino":"Use the pockets of firm sand to time your moves. Check both the next target and the next tide change."},"enseada-fragmento-do-bico":{"nome":"Within Beak’s Reach","objetivo":"Collect the pearl and return to the exit.","ensino":"Reaching the pearl isn’t enough. Wait for a safe turn to collect it, and plan your way back."},"enseada-fresta-da-vazante":{"nome":"An Opening at Low Tide","objetivo":"Collect the pearl beyond the bent sandbank and return.","ensino":"Two tidal flats in a row take the whole low-tide window. The southern return has only one, but the heron changes targets."},"enseada-ecos-do-rasante":{"nome":"Echoes of the Swoop","objetivo":"Collect two pearls from different branches and leave through the center.","ensino":"The patrol alternates between key tiles. Plan both return trips to firm ground, not just your first crossing between shores."},"enseada-vigia-partilhada":{"nome":"Shared Lookout","objetivo":"Occupy both shells without getting caught by the heron’s swoop.","ensino":"On the shorter shore, walls hold one crab still while the other goes around. Check the target before lining up both arrivals."},"enseada-chefe-garca-da-restinga":{"nome":"Heron of the Sandbar","objetivo":"Cross the sandbar and reach the shell without getting caught in a swoop.","ensino":"The heron sweeps several tiles in a row. Use the detours between sandbanks to switch rows when the target appears."},"enseada-chefe-vigia-das-falesias":{"nome":"Cliff Watch","objetivo":"Reach both shells without getting caught in the cliffside swoop.","ensino":"The heron sweeps several tiles in one attack. Plan both routes together so both crabs leave the marked column in time."},"deriva-primeira-balsa":{"nome":"First Sand Strip","objetivo":"Cross the tidal flats and reach the shell.","ensino":"Cross the strips of exposed sand. End your third move on firm ground."},"deriva-duas-margens":{"nome":"Two Shores","objetivo":"Collect the pearl and return to the exit.","ensino":"Compare the short bend with the longer route over firm ground. The Arrival Shell stays closed until you collect the pearl."},"deriva-corrente-cruzada":{"nome":"Crosscurrent","objetivo":"Cross the tidal flats and reach the shell.","ensino":"Cross the strips of exposed sand. End your third move on firm ground."},"deriva-um-passo-ao-cais":{"nome":"One Step to the Jetty","objetivo":"Cross the tidal flats and reach the shell without getting caught by the heron.","ensino":"Cross the strips of exposed sand. Check the heron’s target against the tide’s next move."},"deriva-cais-da-alta":{"nome":"High-Tide Jetty","objetivo":"Cross the tidal flats and reach the shell.","ensino":"Compare the short bend with the longer route over firm ground. End your third move on firm ground."},"deriva-duas-rampas":{"nome":"Two Ramps","objetivo":"Cross the tidal flats and reach the shell.","ensino":"You may need to time the neighboring flats differently. End your third move on firm ground."},"deriva-balsas-alternadas":{"nome":"Alternating Strips","objetivo":"Cross the tidal flats and reach the shell.","ensino":"Plan the return route before crossing the tidal flats. End your third move on firm ground."},"deriva-ida-e-retorno":{"nome":"Out and Back with the Current","objetivo":"Collect the pearl and return to the exit.","ensino":"Cross the strips of exposed sand. The Arrival Shell stays closed until you collect the pearl."},"deriva-dois-ancoradouros":{"nome":"Two Arms of the Coast","objetivo":"Collect both pearls and return to the exit without getting caught by the heron.","ensino":"Compare the short bend with the longer route over firm ground. Check the heron’s target against the tide’s next move."},"deriva-tripulacao-partilhada":{"nome":"Shared Crossing","objetivo":"Collect the pearl and occupy both shells.","ensino":"You may need to time the neighboring flats differently. One direction controls both crabs. The shore can stop one while the other moves on."},"deriva-chefe-mestre-das-correntes":{"nome":"Master of the Currents","objetivo":"Use the cleft to fetch the pearl from the southern shore, then return to the Arrival Shell.","ensino":"Step into the round opening to come out at its matching opening. Both openings stay dry; count the moves to the tide change when crossing the low strip on the other shore."},"deriva-chefe-passagem-das-balsas":{"nome":"Islet Passage","objetivo":"Cross the tidal flats and bring both crabs to their shells without getting caught by the heron.","ensino":"Cross the strips of exposed sand. Check the heron’s target against the tide’s next move. One direction controls both crabs."},"enseada-dupla-vigia":{"nome":"Two on Watch","objetivo":"Reach both shells without getting caught by the heron’s swoop.","ensino":"The upper corner gives you room to adjust the pair’s timing. Check the next target before crossing the flat."},"enseada-dupla-revezamento":{"nome":"Sandbar Relay","objetivo":"Collect the pearls and guide both crabs to their shells.","ensino":"The heron’s route changes tiles. While collecting both pearls on the sandbar’s branches, plan for the swoops on your way back."},"deriva-dupla-cais":{"nome":"Meet at the Two Jetties","objetivo":"Cross the tidal flats and bring both crabs to their shells.","ensino":"You may need to time the neighboring flats differently. One direction controls both crabs. The shore can stop one while the other moves on."},"deriva-dupla-contramao":{"nome":"Shores in Opposite Directions","objetivo":"Collect both pearls and occupy both shells.","ensino":"Plan the return too: the pearl is in the branch opposite the exit. One direction controls both crabs. The shore can stop one while the other moves on."},"grutas-encaixe":{"nome":"Ebb Corridor","objetivo":"Cross the tidal flats and reach the shell.","ensino":"Alternate between dry corridors and low passages. End your third move on firm ground."},"grutas-ordem":{"nome":"Two Chambers, One Sequence","objetivo":"Cross the tidal flats and reach the shell.","ensino":"Alternate between dry corridors and low passages. End your third move on firm ground."},"grutas-retorno":{"nome":"Return at Low Tide","objetivo":"Cross the tidal flats and reach the shell.","ensino":"Watch where the water closes the route between the chambers. End your third move on firm ground."},"grutas-dupla-portao":{"nome":"Two Views of the Cave","objetivo":"Cross the tidal flats and bring both crabs to their shells.","ensino":"Watch where the water closes the route between the chambers. One direction controls both crabs. The shore can stop one while the other moves on."},"grutas-dupla-camaras":{"nome":"Chamber Relay","objetivo":"Collect the pearl and occupy both shells without getting caught by the heron.","ensino":"Your return route can differ from the route to the pearl. Check the heron’s target against the tide’s next move. One direction controls both crabs."},"grutas-alavanca-da-entrada":{"nome":"Shadow at the Entrance","objetivo":"Collect the pearl and return to the exit without getting caught by the heron.","ensino":"Alternate between dry corridors and low passages. Check the heron’s target against the tide’s next move."},"grutas-dobra-da-camara":{"nome":"Chamber Bend","objetivo":"Collect the pearl and return to the exit.","ensino":"Use the cave’s nooks to adjust your timing. The Arrival Shell stays closed until you collect the pearl."},"grutas-coral-portador":{"nome":"Coral Passage","objetivo":"Cross the tidal flats and bring both crabs to their shells.","ensino":"Count the moves to the tide change before leaving the dry chamber. One direction controls both crabs. The shore can stop one while the other moves on."},"grutas-alavanca-distante":{"nome":"The Far Chamber","objetivo":"Collect the pearl and occupy both shells.","ensino":"Your return route can differ from the route to the pearl. One direction controls both crabs. The shore can stop one while the other moves on."},"grutas-boca-labirinto":{"nome":"Mouth of the Maze","objetivo":"Collect both pearls and occupy both shells.","ensino":"Alternate between dry corridors and low passages. One direction controls both crabs. The shore can stop one while the other moves on."},"grutas-trio-tres-refugios":{"nome":"Three Shelters","objetivo":"Cross the tidal flats and guide all three crabs to their shells without getting caught by the heron.","ensino":"Use the cave’s nooks to adjust your timing. Check the heron’s target against the tide’s next move. One direction controls all three crabs."},"grutas-chefe-sentinela-da-gruta":{"nome":"Cave Sentinel","objetivo":"Collect both pearls, take the cleft and reach the Arrival Shell in the chamber.","ensino":"The narrow opening acts as a tunnel when both ends are dry. At high tide, the dry opening becomes ordinary ground. Come back at low tide and cross before it rises."},"grutas-chefe-cofre-das-espumas":{"nome":"Vault of Foam","objetivo":"Collect the pearl and occupy both shells without getting caught by the heron.","ensino":"Your return route can differ from the route to the pearl. Check the heron’s target against the tide’s next move. One direction controls both crabs."},"ressaca-dupla-abrigo":{"nome":"Shelter Between Two Jetties","objetivo":"Occupy both shells.","ensino":"The heron swoops on the indicated turn. End outside the marked area. Raised sand is safe from the tide."},"ressaca-dupla-ancoradouros":{"nome":"Cliffside Relay","objetivo":"Collect the pearl and occupy both shells.","ensino":"The heron swoops on the indicated turn. End outside the marked area. Raised sand is safe from the tide."},"ressaca-refugio-de-pedra":{"nome":"Tidal Shelter","objetivo":"Cross the sandbanks and reach the shell.","ensino":"The first shelter has a pocket of firm sand to the south. Use it to start crossing both flats as soon as the tide falls."},"ressaca-bolsos-opostos":{"nome":"Opposite Pockets","objetivo":"Collect both pearls from opposite ends and exit to the southeast.","ensino":"Use the southern pocket to time the climb to the second pearl. Check the tide on the way out so you don’t get trapped on the way back."},"ressaca-vigia-da-placa":{"nome":"Watch Over the Rocky Shore","objetivo":"Occupy both shells.","ensino":"It’s not enough to get one crab there first. Leave room for the rest to occupy their shells on the same turn."},"ressaca-balsas-da-ponta":{"nome":"Headland Paths","objetivo":"Collect the pearls and reach the Arrival Shell.","ensino":"Plan the return before fetching the pearls. If the water rises, use the firm pockets of sand to time the falling tide."},"ressaca-cais-em-paralelo":{"nome":"Parallel Jetties","objetivo":"Collect the pearl and occupy both shells.","ensino":"It’s not enough to get one crab there first. Leave room for the rest to occupy their shells on the same turn."},"ressaca-tres-moedas-do-cais":{"nome":"Jetty Pearls","objetivo":"Collect the pearls and reach the Arrival Shell.","ensino":"Plan the return before fetching the pearls. If the water rises, use the firm pockets of sand to time the falling tide."},"ressaca-atracadouro-torto":{"nome":"Crooked Mooring","objetivo":"Collect the pearl and occupy both shells.","ensino":"It’s not enough to get one crab there first. Leave room for the rest to occupy their shells on the same turn."},"ressaca-cofre-da-vazante":{"nome":"Vault of the Ebb","objetivo":"Collect the pearls and occupy both shells.","ensino":"Use walls to stagger the crabs’ movement. Everyone gets the same command, but no crab can enter a tile another crab occupied at the start of the move."},"ressaca-chefe-vento-sul":{"nome":"South Wind","objetivo":"Collect the pearls and reach the Arrival Shell.","ensino":"The pearls are near the start, but the exit is at the other end. Use the bends in the firm sand to plan the climb, and watch the heron."},"ressaca-chefe-ressaca-alta":{"nome":"The Bay’s Two Tips","objetivo":"Collect the pearls and occupy both shells.","ensino":"A narrow corridor connects the two shores. Recover the southern pearls before guiding both crabs to the upper shells. Don’t leave either on a tidal flat."},"ressaca-trio-eco-dos-tres-cais":{"nome":"Echo of Three Jetties","objetivo":"Collect the pearl and occupy all three shells.","ensino":"It’s not enough to get one crab there first. Leave room for the rest to occupy their shells on the same turn."},"farol-fragmento-margens":{"nome":"Pearl of the Two Shores","objetivo":"Collect the pearl and occupy both shells.","ensino":"Use walls to stagger the crabs’ movement. Everyone gets the same command, but no crab can enter a tile another crab occupied at the start of the move."},"farol-duas-luzes":{"nome":"The Lighthouse’s Two Lights","objetivo":"Collect the pearls and occupy both shells.","ensino":"The heron swoops on the indicated turn. End outside the marked area. Raised sand is safe from the tide."},"farol-faroleiros-de-vigia":{"nome":"Lighthouse Keepers on Watch","objetivo":"Collect the pearl and occupy both shells.","ensino":"The heron swoops on the indicated turn. End outside the marked area. Raised sand is safe from the tide."},"farol-turno-dos-guardioes":{"nome":"The Guardians’ Watch","objetivo":"Collect the pearls and occupy both shells.","ensino":"The heron swoops on the indicated turn. End outside the marked area. Raised sand is safe from the tide."},"farol-costa-das-tres-luzes":{"nome":"Coast of Three Lights","objetivo":"Collect the pearls and reach the Arrival Shell.","ensino":"Plan the return before fetching the pearls. If the water rises, use the firm pockets of sand to time the falling tide."},"farol-faisca-de-entrada":{"nome":"Spark at the Entrance","objetivo":"Reach the shell.","ensino":"Plan your return before heading out. If the water rises, use the firm pockets of sand to time the falling tide."},"farol-salao-das-lanternas":{"nome":"Hall of Lanterns","objetivo":"Collect the pearl and occupy both shells.","ensino":"Use walls to stagger the crabs’ movement. Everyone gets the same command, but no crab can enter a tile another crab occupied at the start of the move."},"farol-quatro-cais":{"nome":"Four Lighthouse Jetties","objetivo":"Collect the pearls and reach the Arrival Shell.","ensino":"Plan the return before fetching the pearls. If the water rises, use the firm pockets of sand to time the falling tide."},"farol-lentes-em-contramare":{"nome":"Cliffs Against the Tide","objetivo":"Collect the pearl and occupy both shells.","ensino":"Use walls to stagger the crabs’ movement. Everyone gets the same command, but no crab can enter a tile another crab occupied at the start of the move."},"farol-luz-das-duas-mares":{"nome":"Light of Both Tides","objetivo":"Collect the pearls and occupy both shells.","ensino":"One pearl lies to the south and the other near the climb. Plan how to collect both before guiding the pair to the northern shells."},"farol-chefe-guardiao":{"nome":"Lighthouse Guardian","objetivo":"Reach the shell.","ensino":"The exit is on the eastern shore. Stop on the raised sand midway, and plan your return in case the heron cuts off the next stretch."},"farol-trio-tres-luzes":{"nome":"Three Lights in Relay","objetivo":"Occupy all three shells.","ensino":"It’s not enough to get one crab there first. Leave room for the rest to occupy their shells on the same turn."},"farol-chefe-ultima-virada":{"nome":"The Last Turn of the Tide","objetivo":"Occupy all three shells.","ensino":"The shells sit on branches of the same rocky shore. Line up two arrivals before heading down the last ramp. Walls can hold the group in place, but the heron keeps patrolling."},"praia-exp-ramal-da-duna":{"nome":"Dune Spur","objetivo":"Cross the dune’s tidal flat and reach the shell.","ensino":"One bend crosses wet sand. Head down early and clear it before the tide rises."},"praia-exp-degrau-da-vazante":{"nome":"Ebb Steps","objetivo":"Reach the scallop shell at the end of the bend.","ensino":"On the first rise, dry sand at the corner gives you a way forward. The lower branch is a shortcut if the tide is right."},"praia-exp-poquinha-do-sul":{"nome":"The Little Southern Pool","objetivo":"Cross the southern pool to reach the shell’s side.","ensino":"The side flat looks like a dead end, but the bottom row links both shores."},"praia-exp-pescoco-de-areia":{"nome":"Neck of Sand","objetivo":"Cross the narrow tidal flat and follow the shell’s shore.","ensino":"Arriving late needn’t end the run. Use the last dry tile to adjust your move count before going down."},"praia-exp-curva-da-restinga":{"nome":"The Coastal Bend","objetivo":"Reach the shell without entering the marked tile on the heron’s attack turn.","ensino":"The lower detour gets you out of the heron’s sights and lets you return a turn later."},"praia-exp-mira-na-entrada":{"nome":"At the Heron’s Gate","objetivo":"Cross the tidal strip without getting caught by the heron.","ensino":"When the tile ahead is marked, adjust your timing along the dry shore. Get off the wet sand before the next rise."},"praia-exp-duas-beiras":{"nome":"Two Shores of the Islet","objetivo":"Collect the pearl and open the Arrival Shell on the lower shore.","ensino":"The pearl and oyster are on different branches. After collecting the pearl, look for the bend that leads down the shore."},"praia-exp-ilha-do-nacre":{"nome":"Mother-of-Pearl Island","objetivo":"Bring the pearl from the right-hand branch to open the Arrival Shell.","ensino":"You return from a different tip. Count where you’ll be when the tide next rises before stepping back onto the flat."},"praia-exp-janela-do-farolete":{"nome":"The Little Beacon’s Window","objetivo":"Collect the pearl at the far end and return through the left opening.","ensino":"When you leave the pearl’s branch, the open center gives you room to time the return crossing."},"praia-exp-contorno-da-enseada":{"nome":"Around the Cove","objetivo":"Collect the pearl and reach the Arrival Shell across the cove.","ensino":"Collect the pearl before crossing the wet passage. Use the dry branch to get back in step with the tide."},"praia-exp-garca-do-pontal":{"nome":"The Headland Heron","objetivo":"Collect the pearl and reach the Arrival Shell without entering the target tile during an attack.","ensino":"The heron also targets the pearl’s tile. Plan to reach it on a safe turn."},"praia-exp-encontro-de-lagoas":{"nome":"Where the Lagoons Meet","objetivo":"Pass between the lagoons to reach the shell on the eastern shore.","ensino":"Two junctions lead to the same shore. Look at which side of the safe spot puts the next dry tile within easier reach."},"praia-exp-orla-dos-refugios":{"nome":"Shore of Shelters","objetivo":"Reach the shell using both raised patches of sand.","ensino":"The higher shelter stays safe on the first rise. From there, you can take the short passage down or go around."},"praia-exp-ilhas-em-triangulo":{"nome":"Three Islets","objetivo":"Collect both pearls and reach the Arrival Shell.","ensino":"A wet stretch lies between the islets. Use dry sand to line up low tide for the trip there and back."},"praia-exp-linha-do-sernambi":{"nome":"Clamshell Trail","objetivo":"Gather both pearls from the northern branches and leave along the southern route.","ensino":"The central shelter connects both sides. Visit the shore that suits the tide first, then return along the lower route."},"praia-exp-garca-da-vazante":{"nome":"Heron at Low Tide","objetivo":"Collect the pearl and reach the Arrival Shell while avoiding the heron.","ensino":"The shortcut floods at high tide. Adjust your timing on firm sand and check the next warning before heading back."},"praia-exp-duas-luzes-do-cabo":{"nome":"Two Lights on the Cape","objetivo":"Gather both pearls and return to the Arrival Shell on the lower branch.","ensino":"The heron watches the flat near the exit. Leave yourself room on firm sand to plan the final approach."},"praia-exp-asa-sobre-areia":{"nome":"Wings Over Sand","objetivo":"Collect the pearl, avoid the heron and reach the Arrival Shell.","ensino":"Pause on firm sand at the bends before entering a tidal flat. On the way back, the next target matters as much as the turn of the tide."},"recifes-exp-arco-do-coral":{"nome":"Coral Arch","objetivo":"Cross the sand arch and find the shell.","ensino":"You can step onto the shelter, but you don’t have to. Check which route keeps you safe on the first rise."},"recifes-exp-ponte-em-zigue":{"nome":"Zigzag Bridge","objetivo":"Round the shelter and cross to the second sandbank.","ensino":"Use the junction to prepare for the second crossing rather than trying both tidal flats at once."},"recifes-exp-ombro-do-costao":{"nome":"Rocky Shoulder","objetivo":"Reach the shell above the central sandbank.","ensino":"The first rise closes the central shortcut. The lower shoulder gives you room to circle back to the shell’s entrance across dry ground."},"recifes-exp-meia-volta-de-nacre":{"nome":"Mother-of-Pearl Turn","objetivo":"Collect both pearls before returning to the southern exit.","ensino":"After collecting the pearl on the upper branch, decide whether to double back or take the long way around."},"recifes-exp-bacia-estreita":{"nome":"Narrow Basin","objetivo":"Collect the pearls from the basin and the shore before opening the exit.","ensino":"Two routes lead to the eastern branch. Choose the one that lets you leave without waiting on wet sand."},"recifes-exp-poco-do-ourico":{"nome":"Urchin Pool","objetivo":"Collect the pearls and return to the Arrival Shell.","ensino":"The reef’s two branches go to different places. Use the dry route around to catch low tide before reaching the last flat."},"recifes-exp-volta-das-fendas":{"nome":"Around the Clefts","objetivo":"Collect the pearls and reach the Arrival Shell on the far side.","ensino":"A dry path helps you collect them, but the Arrival Shell’s tidal flat is somewhere else. Plan your return before stepping onto it."},"recifes-exp-porta-do-norte":{"nome":"Northern Gate","objetivo":"Explore the north and southeast branches to open the southwest exit.","ensino":"On your way back from the north, don’t commit to the exit crossing until you have the second pearl."},"recifes-exp-costura-de-sal":{"nome":"Salt Seam","objetivo":"Cross the seam, collect the pearl and return to the exit by the jetty.","ensino":"The pearl is at the end of the branch. The important choice is how to get back to the central shelter."},"recifes-exp-ilhas-de-vies":{"nome":"Islands at an Angle","objetivo":"Fetch both pearls and reach the exit on the narrow tip.","ensino":"The shelters sit diagonally opposite each other. Start each trip at the beginning of a new low tide."},"recifes-exp-anel-da-concha":{"nome":"Shell Ring","objetivo":"Enter the ring and find the shell on the upper edge.","ensino":"Use the lower entrance to get the timing right before walking around. The shorter path isn’t necessarily open."},"recifes-exp-margens-de-tres":{"nome":"Three Shores","objetivo":"Recover all three pearls and use the central exit.","ensino":"You can cross the southeast branch two ways. Save the dry central corridor for the return."},"recifes-exp-triangulo-do-baixio":{"nome":"Tidal Triangle","objetivo":"Collect the three pearls at the corners and exit at the bottom.","ensino":"The north and southeast branches meet behind the center. Plan the order to avoid unnecessary trips back and forth."},"recifes-exp-saida-apos-espuma":{"nome":"Beyond the Foam","objetivo":"Cross the reef’s narrow middle, collect the pearls and reach the Arrival Shell on the east.","ensino":"Choose a shelter to end the first half of the route. The final crossing needs different timing from the pearl pickup."},"recifes-exp-coroa-da-vazante":{"nome":"Ebb Crown","objetivo":"Gather all three pearls around the crown and return to the Arrival Shell in the southern corner.","ensino":"The shortcut behind the jetty bypasses the central passage. Time the last circuit before low tide runs out."},"mangue-exp-ramos-curvados":{"nome":"Bending Branches","objetivo":"Occupy both shells at the same time.","ensino":"One branch ends sooner than the other. Use the edge to hold one crab on firm ground while the other rounds the tidal bend."},"mangue-exp-fenda-das-raizes":{"nome":"Cleft Between Roots","objetivo":"Guide both crabs to the two shells.","ensino":"The sand branches meet in the middle. Backtracking over dry ground changes which crab enters the wet stretch first."},"mangue-exp-ilhas-de-dois-passos":{"nome":"Two-Step Islands","objetivo":"Occupy both shells with the two crabs.","ensino":"Reach both shelters before the water rises. The firm pocket lets you adjust your timing without straying from the shell."},"mangue-exp-grampos-de-areia":{"nome":"Hooks of Sand","objetivo":"Occupy both shells with the two crabs.","ensino":"The routes turn in different directions. Use the shelters to line up the pair before crossing the flats near the shells."},"mangue-exp-lacada-do-lodo":{"nome":"Mud Loop","objetivo":"Occupy both shells with the two crabs.","ensino":"Use the long bend to switch which crab is in front. Alternate shelters so neither crab is on a flat when the tide rises."},"mangue-exp-placa-na-quina":{"nome":"Shell at the Corner","objetivo":"Get both crabs onto their shells at the same time.","ensino":"The corners let each crab move at a different point in the route. Check both shores before crossing the flat near the shell."},"mangue-exp-porta-de-costas":{"nome":"Rounding the Bend Backward","objetivo":"Bring the crabs together at the shells on opposite shores.","ensino":"The upper path goes around the flat. A well-placed step back changes the gap between the crabs before they arrive."},"mangue-exp-vigilia-do-trinco":{"nome":"Watch Among the Roots","objetivo":"Occupy both shells at the same time.","ensino":"Use the upper roots to change how the pair lines up. Move back and forth on firm ground to wait for low tide without leaving either crab behind."},"mangue-exp-siri-nas-bifurcacoes":{"nome":"Crabs at the Forks","objetivo":"Collect the pearls and occupy both shells.","ensino":"Use each fork to collect a pearl without sending your partner onto a flat on the rising tide. Return to both shells on the same turn."},"mangue-exp-coroa-de-lodo":{"nome":"Crown of Mud","objetivo":"Collect the pearls and occupy both shells.","ensino":"Pick up the pearls in both branches of the crown. Use the firm edges to rearrange the pair before heading down to the shell."},"mangue-exp-nicho-de-cruzamento":{"nome":"Passing Nook","objetivo":"Occupy both shells with the two crabs.","ensino":"The crabs start face to face. The side nook lets you change their spacing before reaching the two ends of the crossing."},"mangue-exp-raiz-que-fica":{"nome":"The Root That Stays","objetivo":"Bring both crabs together at their shells.","ensino":"The central root splits the paths. Use the firm tip to switch who goes first without missing low tide at the flat."},"mangue-exp-meia-volta-na-placa":{"nome":"U-Turn on the Flats","objetivo":"Guide both crabs to the shells.","ensino":"Circle along the lower shore before heading up. Watch where each crab stops while the other rounds a bend."},"mangue-exp-galeria-das-sementes":{"nome":"Pearl Gallery","objetivo":"Collect the pearls and occupy both shells.","ensino":"The pearls are on different shores. Use the middle detour to collect one without sending the other crab into the water when the tide rises."},"mangue-exp-manguezal-em-espiral":{"nome":"Mangrove Spiral","objetivo":"Collect the pearls and bring both crabs to their shells.","ensino":"The sand spiral brings you through the middle more than once. Check the tide and both crabs’ positions before switching branches."},"enseada-exp-onda-no-degrau":{"nome":"Ebb on the Steps","objetivo":"Cross the sand steps and reach the shell.","ensino":"Each bend changes which tile the heron can reach. Enter the wet stretch only if you have time to clear it."},"enseada-exp-areia-em-forquilha":{"nome":"Fork in the Sand","objetivo":"Reach the shell along the branch that opens at low tide.","ensino":"The dry sand at the base of the fork lets you switch branches without ending up in the water or in the heron’s sights."},"enseada-exp-no-vai-e-vem":{"nome":"Back and Forth","objetivo":"Reach the shell without getting caught by the heron’s swoop.","ensino":"If the tide or heron blocks the crossing, use the dry nook to get the timing right."},"enseada-exp-escadinha-da-restinga":{"nome":"Sandbar Steps","objetivo":"Reach the shell without getting caught by the heron’s swoop.","ensino":"The sand staircase has two tidal steps. Use the firm nooks to time each climb."},"enseada-exp-margem-em-anel":{"nome":"Ring Shore","objetivo":"Reach the shell while avoiding the heron.","ensino":"Use the dry arc when water blocks the crossing. Plan to return through the flat rather than closing the loop at high tide."},"enseada-exp-ilha-da-sombra-curta":{"nome":"Island of the Short Shadow","objetivo":"Reach the shell without getting caught by the heron’s swoop.","ensino":"Watch the target on the final climb. The tidal flat and the swoop can close passages on different turns."},"enseada-exp-degraus-do-bico":{"nome":"Steps Within Reach","objetivo":"Reach the shell without getting caught by the heron’s swoop.","ensino":"A dry step gives you a place to wait, but the heron keeps coming back to the middle of the climb."},"enseada-exp-ponta-da-restinga-oeste":{"nome":"West Sandbar Point","objetivo":"Collect the pearl and reach the Arrival Shell while avoiding the swoop.","ensino":"The pearl is on the outer branch. Backtrack along firm sand to time the flat crossing and keep a safe distance on the way back."},"enseada-exp-rosa-dos-ventos":{"nome":"Compass Rose","objetivo":"Collect all the pearls and reach the exit.","ensino":"The tips take different numbers of moves to return from. Use the central sand to time the trip down each branch."},"enseada-exp-cais-fora-da-sombra":{"nome":"A Jetty Out of the Shadow","objetivo":"Collect all the pearls and reach the exit.","ensino":"The heron alternates between the exit and the northern crossing. You don’t have to take the same branch both ways."},"enseada-exp-triangulo-da-vazante":{"nome":"Ebb Triangle","objetivo":"Collect the pearls and return to the Arrival Shell.","ensino":"The outer branch bypasses the swoop, but the last crossing still needs low tide. Think about the return when you choose your first pearl."},"enseada-exp-folha-sobre-a-agua":{"nome":"Leaf on the Water","objetivo":"Collect the pearls at the tips of the sandbar and reach the Arrival Shell.","ensino":"Each trip has a different pocket of dry sand. Time the tide before heading up the first branch, and check the target on your way back."},"enseada-exp-posto-da-vigia":{"nome":"Watch Post","objetivo":"Guide both crabs to the watch post’s shells without getting caught by the heron.","ensino":"Check the target and use the firm corners of the post to protect both crabs with the same command."},"enseada-exp-dois-olhares":{"nome":"Two Views of the Jetty","objetivo":"Bring both crabs to their shells without leaving either in the heron’s sights.","ensino":"Check the shore a command leaves behind as well as the one it moves toward. Cross the flat only if the move is safe for the other crab too."},"enseada-exp-entrelace-da-restinga":{"nome":"Interwoven Sandbar","objetivo":"Collect the pearls and bring both crabs to the shells.","ensino":"Each shore has a pearl. Use the nooks and bends to split up the pair and avoid attacks on the return."},"deriva-exp-calheta":{"nome":"Horseshoe Inlet","objetivo":"Cross the tidal flats and reach the shell.","ensino":"Compare the short bend with the longer route over firm ground. End your third move on firm ground."},"deriva-exp-cais-suspenso":{"nome":"Suspended Jetty","objetivo":"Cross the tidal flats and reach the shell.","ensino":"You may need to time the neighboring flats differently. End your third move on firm ground."},"deriva-exp-vazante":{"nome":"Ebb Crossing","objetivo":"Cross the tidal flats and reach the shell.","ensino":"Plan the return route before crossing the tidal flats. End your third move on firm ground."},"deriva-exp-pedra-em-meia-lua":{"nome":"Crescent Stone","objetivo":"Cross the tidal flats and reach the shell.","ensino":"Cross the strips of exposed sand. End your third move on firm ground."},"deriva-exp-dente-do-cais":{"nome":"Tooth of the Jetty","objetivo":"Collect the pearl and return to the exit.","ensino":"You may need to time the neighboring flats differently. The Arrival Shell stays closed until you collect the pearl."},"deriva-exp-alca-salgada":{"nome":"Saltwater Loop","objetivo":"Collect the pearl and return to the exit.","ensino":"Plan the return too: the pearl is in the branch opposite the exit. The Arrival Shell stays closed until you collect the pearl."},"deriva-exp-dois-bracos-de-pedra":{"nome":"Two Arms of Stone","objetivo":"Collect both pearls and return to the exit.","ensino":"Compare the short bend with the longer route over firm ground. The Arrival Shell stays closed until you collect the pearls."},"deriva-exp-dunas-trocadas":{"nome":"Swapped Dunes","objetivo":"Cross the tidal flats and reach the shell without getting caught by the heron.","ensino":"You may need to time the neighboring flats differently. Check the heron’s target against the tide’s next move."},"deriva-exp-correntes-em-l":{"nome":"L-Shaped Currents","objetivo":"Cross the tidal flats and reach the shell.","ensino":"Plan the return route before crossing the tidal flats. End your third move on firm ground."},"deriva-exp-bifurcacao-safira":{"nome":"Sapphire Fork","objetivo":"Collect the pearl and return to the exit.","ensino":"Cross the strips of exposed sand. The Arrival Shell stays closed until you collect the pearl."},"deriva-exp-escada-das-tres-ilhas":{"nome":"Stairway of Three Islands","objetivo":"Cross the tidal flats and reach the shell.","ensino":"Compare the short bend with the longer route over firm ground. End your third move on firm ground."},"deriva-exp-ultimas-estacas":{"nome":"The Last Pilings","objetivo":"Collect the pearl and return to the exit.","ensino":"You may need to time the neighboring flats differently. The Arrival Shell stays closed until you collect the pearl."},"deriva-exp-guarda-do-canal":{"nome":"Channel Watch","objetivo":"Cross the tidal flats and bring both crabs to their shells without getting caught by the heron.","ensino":"Plan the return route before crossing the tidal flats. Check the heron’s target against the tide’s next move. One direction controls both crabs."},"deriva-exp-placa-na-ilhota":{"nome":"Meeting on the Islet","objetivo":"Cross the tidal flats and bring both crabs to their shells.","ensino":"Cross the strips of exposed sand. One direction controls both crabs. The shore can stop one while the other moves on."},"deriva-exp-retorno-em-revezamento":{"nome":"Relay Return","objetivo":"Collect both pearls and occupy both shells.","ensino":"The shores join along a strip that disappears at high tide. Position the two crabs so they can collect pearls in different directions."},"grutas-exp-perola-no-mezanino":{"nome":"Sand Mezzanine","objetivo":"Cross the tidal flats and reach the shell.","ensino":"Use the cave’s nooks to adjust your timing. End your third move on firm ground."},"grutas-exp-biblioteca-submersa":{"nome":"Submerged Library","objetivo":"Collect the pearl and return to the exit.","ensino":"Count the moves to the tide change before leaving the dry chamber. The Arrival Shell stays closed until you collect the pearl."},"grutas-exp-coluna-de-vidro":{"nome":"Glass Column","objetivo":"Collect the pearl and return to the exit.","ensino":"Your return route can differ from the route to the pearl. The Arrival Shell stays closed until you collect the pearl."},"grutas-exp-mapas-na-parede":{"nome":"Maps on the Wall","objetivo":"Collect the pearl and return to the exit.","ensino":"Use the cave’s nooks to adjust your timing. The Arrival Shell stays closed until you collect the pearl."},"grutas-exp-alavanca-no-oco":{"nome":"A Light in the Hollow","objetivo":"Collect the pearl and return to the exit.","ensino":"Count the moves to the tide change before leaving the dry chamber. The Arrival Shell stays closed until you collect the pearl."},"grutas-exp-cisterna-de-areia":{"nome":"Sand Cistern","objetivo":"Collect the pearl and return to the exit.","ensino":"Alternate between dry corridors and low passages. The Arrival Shell stays closed until you collect the pearl."},"grutas-exp-perola-em-ziguezague":{"nome":"Zigzag Pearl","objetivo":"Collect the pearl and return to the exit.","ensino":"Use the cave’s nooks to adjust your timing. The Arrival Shell stays closed until you collect the pearl."},"grutas-exp-varanda-das-conchas":{"nome":"Shell Balcony","objetivo":"Cross the tidal flats and reach the shell without getting caught by the heron.","ensino":"Count the moves to the tide change before leaving the dry chamber. Check the heron’s target against the tide’s next move."},"grutas-exp-margens-da-fechadura":{"nome":"Across the Chamber","objetivo":"Collect the pearl and occupy both shells.","ensino":"Alternate between dry corridors and low passages. One direction controls both crabs. The shore can stop one while the other moves on."},"grutas-exp-entre-estalactites":{"nome":"Between Stalactites","objetivo":"Cross the tidal flats and bring both crabs to their shells.","ensino":"Use the cave’s nooks to adjust your timing. One direction controls both crabs. The shore can stop one while the other moves on."},"grutas-exp-rua-dos-refugios":{"nome":"Lane of Shelters","objetivo":"Collect the pearl and occupy both shells.","ensino":"Count the moves to the tide change before leaving the dry chamber. One direction controls both crabs. The shore can stop one while the other moves on."},"grutas-exp-claraboia-partilhada":{"nome":"Shared Skylight","objetivo":"Cross the tidal flats and bring both crabs to their shells.","ensino":"Alternate between dry corridors and low passages. One direction controls both crabs. The shore can stop one while the other moves on."},"grutas-exp-galerias-em-espelho":{"nome":"Mirror Galleries","objetivo":"Collect both pearls and occupy both shells.","ensino":"The bends branch from the same staircase. Collect both pearls and line up the arrivals without letting the crabs block each other in the narrow corridor."},"grutas-exp-ponte-do-diapiro":{"nome":"Diapir Bridge","objetivo":"Collect the pearl and occupy both shells.","ensino":"Both galleries meet in one corridor. The rear crab can’t enter the tile the front crab started on. Use the nook to get them in order and cross the flat."},"grutas-exp-agulha-da-vazante":{"nome":"Needle at Low Tide","objetivo":"Collect both pearls and occupy both shells.","ensino":"Your return route can differ from the route to the pearl. One direction controls both crabs. The shore can stop one while the other moves on."},"ressaca-exp-dobras":{"nome":"Folds of the Breakers","objetivo":"Reach the shell at the north end of the bay.","ensino":"Use the middle of the bend to line up two moves across the flat. Your third move takes you out on the far side."},"ressaca-exp-leques":{"nome":"Fans of Foam","objetivo":"Bring both pearls to the exit.","ensino":"The oyster opens only once you have both pearls. In the eastern fan, use the path above the exit so you don’t have to cross the same flat again."},"ressaca-exp-mastro":{"nome":"Shadow of the Mast","objetivo":"Collect the pearls along the two loops and exit to the south.","ensino":"The heron sweeps the marked line. Move safely around the shelter while you wait for an opening."},"ressaca-exp-revezamento":{"nome":"Rocky-Shore Relay","objetivo":"Occupy both shells.","ensino":"It’s not enough to get one crab there first. Leave room for the rest to occupy their shells on the same turn."},"ressaca-exp-cotovelo":{"nome":"Sand Bend","objetivo":"Collect the pearl and reach the Arrival Shell.","ensino":"Plan the return before fetching the pearl. If the water rises, use the firm pockets of sand to time the falling tide."},"ressaca-exp-pontal":{"nome":"Against the Headland","objetivo":"Collect the pearl and reach the Arrival Shell.","ensino":"Plan the return before fetching the pearl. If the water rises, use the firm pockets of sand to time the falling tide."},"ressaca-exp-corredores":{"nome":"Wind Corridors","objetivo":"Occupy both shells.","ensino":"Use walls to stagger the crabs’ movement. Everyone gets the same command, but no crab can enter a tile another crab occupied at the start of the move."},"ressaca-exp-balizas":{"nome":"Rocky-Shore Markers","objetivo":"Collect the pearl and occupy both shells.","ensino":"It’s not enough to get one crab there first. Leave room for the rest to occupy their shells on the same turn."},"ressaca-exp-coroa":{"nome":"Crown of Shells","objetivo":"Collect the pearls and reach the Arrival Shell.","ensino":"Plan the return before fetching the pearls. If the water rises, use the firm pockets of sand to time the falling tide."},"ressaca-exp-ondas":{"nome":"Cliffside Stairs","objetivo":"Climb the cliff by way of the sandbanks and reach the shell.","ensino":"Start across the two sandbanks as soon as the tide falls. Use the firm landing to time the next crossing without walking back over the flat."},"ressaca-exp-argolas":{"nome":"Arch of Three Pearls","objetivo":"Collect the pearls and reach the Arrival Shell.","ensino":"Plan the return before fetching the pearls. If the water rises, use the firm pockets of sand to time the falling tide."},"ressaca-exp-flutuantes":{"nome":"Bends in the Escarpment","objetivo":"Collect the pearl and occupy both shells.","ensino":"Use walls to stagger the crabs’ movement. Everyone gets the same command, but no crab can enter a tile another crab occupied at the start of the move."},"ressaca-exp-boias":{"nome":"Three Meeting Buoys","objetivo":"Guide all three crabs to their shells.","ensino":"All three crabs take the same command. A rock wall can hold one crab in place while the others continue along their paths."},"ressaca-exp-laminas":{"nome":"The Three-Route Nook","objetivo":"Collect the pearls and occupy all three shells.","ensino":"It’s not enough to get one crab there first. Leave room for the rest to occupy their shells on the same turn."},"ressaca-exp-rebentacao":{"nome":"Dock of Mirrors","objetivo":"Collect the pearls and occupy all three shells.","ensino":"Use walls to stagger the crabs’ movement. Everyone gets the same command, but no crab can enter a tile another crab occupied at the start of the move."},"farol-exp-sinos":{"nome":"Bells at the Harbor Mouth","objetivo":"Collect the pearl and occupy both shells.","ensino":"It’s not enough to get one crab there first. Leave room for the rest to occupy their shells on the same turn."},"farol-exp-lastros":{"nome":"Opposing Ballasts","objetivo":"Collect the pearl and occupy both shells.","ensino":"Use walls to stagger the crabs’ movement. Everyone gets the same command, but no crab can enter a tile another crab occupied at the start of the move."},"farol-exp-sentinelas":{"nome":"Sentinels at the Lookout","objetivo":"Collect the pearl and occupy both shells.","ensino":"The heron swoops on the indicated turn. End outside the marked area. Raised sand is safe from the tide."},"farol-exp-prumos":{"nome":"Plumb Lines of the Cliff","objetivo":"Collect the pearl and occupy both shells.","ensino":"The heron swoops on the indicated turn. End outside the marked area. Raised sand is safe from the tide."},"farol-exp-bolsao":{"nome":"Pocket of Three Pearls","objetivo":"Collect all three pearls in any order and reach the Arrival Shell at the tip of the rocky shore.","ensino":"More than one route links the three tips. Before choosing the next pearl, find a shelter that lets you cross the flat just after the tide falls."},"farol-exp-agulha":{"nome":"Needle of Glass","objetivo":"Reach the shell.","ensino":"Plan your return before heading out. If the water rises, use the firm pockets of sand to time the falling tide."},"farol-exp-janelas":{"nome":"Windows of Pale Sand","objetivo":"Reach the shell.","ensino":"Plan your return before heading out. If the water rises, use the firm pockets of sand to time the falling tide."},"farol-exp-charneira":{"nome":"Strait of Three Docks","objetivo":"Collect the pearls and reach the Arrival Shell.","ensino":"Plan the return before fetching the pearls. If the water rises, use the firm pockets of sand to time the falling tide."},"farol-exp-cadeado":{"nome":"Mother-of-Pearl Galleries","objetivo":"Collect the pearl and occupy both shells.","ensino":"It’s not enough to get one crab there first. Leave room for the rest to occupy their shells on the same turn."},"farol-exp-quadrante":{"nome":"Sand Quadrant","objetivo":"Reach the shell.","ensino":"Plan your return before heading out. If the water rises, use the firm pockets of sand to time the falling tide."},"farol-exp-prisma":{"nome":"Crossing Paths","objetivo":"Occupy both shells.","ensino":"It’s not enough to get one crab there first. Leave room for the rest to occupy their shells on the same turn."},"farol-exp-tripode":{"nome":"The Watcher’s Lookout","objetivo":"Occupy all three shells.","ensino":"Use walls to stagger the crabs’ movement. Everyone gets the same command, but no crab can enter a tile another crab occupied at the start of the move."},"farol-exp-ampulheta":{"nome":"Hourglass of Sand","objetivo":"Occupy all three shells.","ensino":"It’s not enough to get one crab there first. Leave room for the rest to occupy their shells on the same turn."},"farol-exp-ocaso":{"nome":"Sunset Galleries","objetivo":"Occupy all three shells.","ensino":"The heron’s patrol and the tide follow different rhythms. Use walls to give the three crabs space before lining up their arrivals."},"farol-exp-poente":{"nome":"The Sunset Beacon","objetivo":"Occupy all three shells.","ensino":"Not every turn needs to bring the trio closer to the shells. Leave room to turn around without blocking the corridors."},"enseada-fenda-entre-rochas":{"nome":"Between Two Clefts","objetivo":"Cross a tidal flat and a cleft to reach the shell.","ensino":"Enter the flat at low tide and leave through the round opening. Matching openings are linked, and traveling through a cleft takes one move."},"enseada-fenda-da-vazante":{"nome":"The Ebb Cleft","objetivo":"Wait for low tide and take the cleft to the shell.","ensino":"When one opening floods, the dry opening becomes ordinary ground. Go around below, step onto it at high tide, then step off to make the tide fall. Enter it again. If the tide rises on the move when you arrive, the crab is swept away."},"laboratorio-tres-perolas":{"nome":"Three Pearls on the Sandbar","objetivo":"Collect three pearls and return to the Arrival Shell.","ensino":"Two branches start on tidal flats. Use firm sand to time your next crossing."}};
